import pytest

from bedrock_protocol import v1001, v2168, v2225

# generated by gophertunnel b8bd735:
# &packet.UpdateSubChunkBlocks{Position: protocol.BlockPos{4, -5, 6},
#   Blocks: []protocol.BlockChangeEntry{{BlockPos: protocol.BlockPos{1, 2, 3}, BlockRuntimeID: 300,
#     Flags: 200, SyncedUpdateEntityUniqueID: 9, SyncedUpdateType: 2}},
#   Extra: []protocol.BlockChangeEntry{{BlockPos: protocol.BlockPos{-1, 0, 1}, BlockRuntimeID: 5}}}
WITH_BLOCKS = bytes.fromhex("08090c01020406ac02c80109020101000205000000")

# generated by gophertunnel b8bd735:
# &packet.UpdateSubChunkBlocks{Position: protocol.BlockPos{0, 64, 0}}
EMPTY = bytes.fromhex("008001000000")

GOLDENS = [
    pytest.param(
        v2225.UpdateSubChunkBlocksPacket(
            sub_chunk_block_position=v2225.BlockPos(x=4, y=-5, z=6),
            blocks_changed=v2225.UpdateSubChunkBlocksChangedInfo(
                standards=[
                    v2225.UpdateSubChunkNetworkBlockInfo(
                        pos=v2225.BlockPos(x=1, y=2, z=3),
                        runtime_id=300,
                        update_flags=200,
                        entity_unique_id=9,
                        message=v2225.ActorBlockSyncMessage.MessageId.DESTROY,
                    )
                ],
                extras=[
                    v2225.UpdateSubChunkNetworkBlockInfo(
                        pos=v2225.BlockPos(x=-1, y=0, z=1),
                        runtime_id=5,
                        update_flags=0,
                        entity_unique_id=0,
                        message=v2225.ActorBlockSyncMessage.MessageId.NONE,
                    )
                ],
            ),
        ),
        WITH_BLOCKS,
        id="with-blocks",
    ),
    pytest.param(
        v2225.UpdateSubChunkBlocksPacket(sub_chunk_block_position=v2225.BlockPos(x=0, y=64, z=0)),
        EMPTY,
        id="empty-layers",
    ),
]


@pytest.mark.parametrize("version", [v1001, v2168, v2225])
def test_update_sub_chunk_blocks_is_packet_172(version):
    assert version.packets[172] is version.UpdateSubChunkBlocksPacket


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_sub_chunk_blocks_encodes_to_its_golden(packet, golden):
    assert bytes(packet) == golden


@pytest.mark.parametrize(("packet", "golden"), GOLDENS)
def test_update_sub_chunk_blocks_decodes_from_its_golden(packet, golden):
    assert type(packet).from_bytes(golden) == packet


@pytest.mark.parametrize(
    "body",
    [
        pytest.param(WITH_BLOCKS[:13], id="missing-extras"),
        pytest.param(WITH_BLOCKS[:4], id="missing-blocks"),
    ],
)
def test_update_sub_chunk_blocks_rejects_a_truncated_body(body):
    with pytest.raises(ValueError, match="at byte"):
        v2225.UpdateSubChunkBlocksPacket.from_bytes(body)
